import SwiftUI

/// A field holding a value of a schema, as a section of its parts under
/// its label, or a list of them, as a repeating group: an item per value
/// with its parts and a button that removes it, and a button that adds one
/// while there are fewer than the maximum.
public struct ValueField: View {
    let field: FieldSchema
    /// The path the form holds the value under: the field's name, or the path to a part.
    let path: String
    @Binding var values: Values
    let problems: [String: String]
    let texts: Texts
    let readOnly: Bool

    public var body: some View {
        if field.type == .value {
            Section(say(texts, field.label)) {
                if let problem = problems[path] {
                    Text(problem).foregroundStyle(.red)
                }
                parts(at: path)
            }
        } else {
            Section(say(texts, field.label)) {
                if let problem = problems[path] {
                    Text(problem).foregroundStyle(.red)
                }
                ForEach(0..<HeldValues.countOf(values, path), id: \.self) { index in
                    VStack(alignment: .leading) {
                        parts(at: path + "." + String(index))
                        if !readOnly {
                            Button(say(texts, "screens.removeItem"), role: .destructive) { values = HeldValues.removeItem(values, path, index) }
                        }
                    }
                }
                if !readOnly {
                    Button(say(texts, "screens.addItem")) { values = HeldValues.addItem(field, values, path) }
                        .disabled(field.maximum.map { Double(HeldValues.countOf(values, path)) >= $0 } ?? false)
                }
            }
        }
    }

    @ViewBuilder private func parts(at: String) -> some View {
        ForEach(field.parts ?? [], id: \.name) { part in
            if HeldValues.holdsValue(part) {
                ValueField(field: part, path: at + "." + part.name, values: $values, problems: problems, texts: texts, readOnly: readOnly)
            } else {
                Field(
                    field: part,
                    value: Binding(get: { values[at + "." + part.name] ?? "" }, set: { values[at + "." + part.name] = $0 }),
                    problem: problems[at + "." + part.name],
                    texts: texts,
                    readOnly: readOnly || part.readOnly == true
                )
            }
        }
    }
}
